import React, { useState, useEffect } from 'react';
import { getLatestMovies } from '../api/tmdb';

function MovieSlider() {
  const [movies, setMovies] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);

  useEffect(() => {
    const fetchMovies = async () => {
      const data = await getLatestMovies();
      setMovies(data);
    };
    fetchMovies();
  }, []);

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev === 0 ? movies.length - 1 : prev - 1));
  };

  const handleNext = () => {
    setCurrentIndex((prev) => (prev === movies.length - 1 ? 0 : prev + 1));
  };

  return (
    <div className="main-slider-container">
      {/* 중앙 브랜드 로고 및 타이틀 */}
      <div className="hero-brand">
        <div className="brand-logo">◈</div>
        <h1>Oli Studio</h1>
      </div>

      {/* 정밀 계산된 아치형 굴곡 슬라이더 영역 */}
      <div className="curved-slider-wrapper">
        <button className="slider-arrow left" onClick={handlePrev}>&lt;</button>
        
        <div className="curved-slider-track">
          {movies.map((movie, index) => {
            const offset = (index - currentIndex + movies.length) % movies.length;
            let displayOffset = offset;
            if (offset > movies.length / 2) {
              displayOffset -= movies.length;
            }

            const absOffset = Math.abs(displayOffset);
            
            // 💡 굴곡 및 크기 정밀 계산 공식
            const translateX = displayOffset * 135; // 카드 간 수평 간격
            const translateY = Math.pow(absOffset, 1.8) * 18; // 중앙은 아래로, 바깥은 위로 가파르게 솟는 곡선
            const scale = 0.65 + (absOffset * 0.12); // 중앙이 가장 작고, 바깥으로 갈수록 커짐
            const rotateY = displayOffset * -18; // 양옆 카드가 안쪽을 바라보는 3D 각도
            const opacity = absOffset > 3 ? 0 : 1;

            return (
              <div
                key={movie.id}
                className={`slider-card ${displayOffset === 0 ? 'active' : ''}`}
                style={{
                  transform: `translateX(${translateX}px) translateY(${translateY}px) scale(${scale}) rotateY(${rotateY}deg)`,
                  zIndex: movies.length - absOffset,
                  opacity: opacity,
                  pointerEvents: opacity === 0 ? 'none' : 'auto',
                }}
                onClick={() => setCurrentIndex(index)}
              >
                <img
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`}
                  alt={movie.title}
                />
              </div>
            );
          })}
        </div>

        <button className="slider-arrow right" onClick={handleNext}>&gt;</button>
      </div>

      {/* 하단 설명 및 버튼 */}
      <p className="hero-desc">
        Bring your story to life with AI-powered comic panels. Experience flawless<br />
        consistency, perfect proportions, and impeccable perspective in every frame.
      </p>

      <div className="hero-actions">
        <button className="btn-primary">Get Started Now</button>
        <button className="btn-secondary">Case studies</button>
      </div>
    </div>
  );
}

export default MovieSlider;
